/**
 * Applies the person form's and the claim form's rules to a quick add, before anything is stored:
 * the name is required (and trimmed), the amount is 0.00 or more with up to two decimals. Publishes
 * the person as it would be added (grade A) and the draft claim (the sheet's today, an empty note).
 */
public class ValidateQuickAdd {
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody QuickAddRequest request,
            SheetStore sheets, Out<PersonRequest> person, Out<ClaimInput> claim) throws InvalidSheetException {
        if (request == null || request.name() == null || request.name().trim().isEmpty()) {
            throw new InvalidSheetException("A name is required");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number of 0.00 or more with up to two decimals");
        }
        person.set(new PersonRequest(request.name().trim(), "A", request.user(), null));
        claim.set(new ClaimInput(new BigDecimal(amount).setScale(2), sheets.today(sheetId.trim()), "",
                request.user()));
    }
}
# POST /api/sheets/{sheetId}/quick-add — add a DRAFT claim for a person by name (body: {name, amount,
# user}), dated the sheet's today with an empty note. A name not on the sheet (ignoring case and the
# spaces around it) adds the person first, with grade A. The person form's and the claim form's
# rules apply: refused (400), storing nothing and recording nothing, when the name is empty, the
# amount is not valid, or the sheet's today falls in a closed period. The whole quick add is one
# change: the person is added only once the claim has passed every check.
# Records PERSON_ADDED (and its ROLLUP) for a new person, then CLAIM_ADDED.
validate:
  class: net.officefloor.hq.app.quick.ValidateQuickAdd
  next: checkDate
checkDate:
  class: net.officefloor.hq.app.claim.CheckDatePeriod
  govern: [ transaction ]
  next: person
