  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimAdded
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# PUT /api/sheets/{sheetId}/claims/{claimId} — edit a draft claim's amount, date and note (body as an
# add). Refused (400) like an add, when the claim is not on the sheet, when it is not a DRAFT
# (an open claim is voided and added anew instead), or
# when its date or its new date falls in a closed period; nothing is stored then.
# A stored change is recorded in the audit file as CLAIM_EDITED; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkDraft
checkDraft:
  class: net.officefloor.hq.app.claim.CheckClaimDraft
  govern: [ transaction ]
  next: checkClaim
checkClaim:
