package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim added to a retired person dated after the date they are retired from. */
public class CheckRetired {
    public void check(@Val ClaimInput input, @Val Person person) throws InvalidSheetException {
        refuseRetired(person, input.date());
    }

    public static void refuseRetired(Person person, LocalDate date) throws InvalidSheetException {
        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
            throw new InvalidSheetException(person.getName() + " is retired from " + person.getRetiredFrom());
        }
    }
}
